  async activateLocationWithEvidence(context:TenantContext,value:LocationActivation,evidence:OnboardingActivationEvidence){requireOnboardingActivationScope(context,value,evidence);const client=await this.pool.connect();try{await client.query('BEGIN');await client.query('SELECT pg_advisory_xact_lock(hashtext($1))',[`${context.tenantId}:${context.locationId}:onboarding-activation`]);const latest=await client.query<{record:OnboardingRun}>('SELECT record FROM onboarding_runs WHERE tenant_id=$1 AND location_id=$2 ORDER BY created_at DESC LIMIT 1 FOR UPDATE',[context.tenantId,context.locationId]);const run=latest.rows[0]?.record;if(!run||run.id!==value.onboardingRunId||run.status!=='passed')throw new Error('ONBOARDING_TESTS_STALE');const activation=await client.query<{record:LocationActivation}>(`INSERT INTO location_activations (tenant_id,location_id,status,onboarding_run_id,activated_at,activated_by,updated_at,record) VALUES ($1,$2,$3,$4,$5,$6,$7,$8) ON CONFLICT (tenant_id,location_id) DO UPDATE SET status=EXCLUDED.status,onboarding_run_id=EXCLUDED.onboarding_run_id,activated_at=EXCLUDED.activated_at,activated_by=EXCLUDED.activated_by,updated_at=EXCLUDED.updated_at,record=EXCLUDED.record RETURNING record`,[value.tenantId,value.locationId,value.status,value.onboardingRunId,value.activatedAt,value.activatedBy,value.updatedAt,value]);const resumed=await client.query(`UPDATE workflow_jobs SET status='pending',attempts=0,run_at=$3,last_error=NULL,updated_at=$3 WHERE tenant_id=$1 AND location_id=$2 AND status='paused' AND last_error LIKE 'onboarding:%'`,[context.tenantId,context.locationId,evidence.occurredAt]);const resumedWorkflows=resumed.rowCount??0;const event=onboardingActivationEvent(context,value,resumedWorkflows,evidence);await client.query('INSERT INTO domain_events (event_id,tenant_id,location_id,event_type,occurred_at,correlation_id,schema_version,record) VALUES ($1,$2,$3,$4,$5,$6,$7,$8)',[event.eventId,event.tenantId,event.locationId,event.eventType,event.occurredAt,event.correlationId,event.schemaVersion,event]);await client.query('INSERT INTO outbox_events (event_id,tenant_id,location_id,record) VALUES ($1,$2,$3,$4)',[event.eventId,event.tenantId,event.locationId,event]);await appendChainedAuditInTransaction(client,onboardingActivationAudit(context,value,resumedWorkflows,evidence));await client.query('COMMIT');return{activation:activation.rows[0]!.record,resumedWorkflows}}catch(error){await client.query('ROLLBACK');throw error}finally{client.release()}}
