  async getOwnerReviewData(context:TenantContext,since:string,to:string):Promise<TenantOwnerReviewData>{
    if(context.role!=='owner')throw new Error('OWNER_REVIEW_ACCESS_REQUIRED');const client=await this.pool.connect()
    try{
      await client.query('BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY')
      const[portfolio,conversations,reviews,recoveryApprovals,reconciliation,rateLimits,audit,modelUsage,modelPrices,cohorts,securityIncidents]=await Promise.all([
        postgresTenantPortfolioData(client,context.tenantId,since,to),
        client.query<{record:Conversation}>(`SELECT record FROM conversations WHERE tenant_id=$1 AND intent IN ('complaint','medical_safety') AND updated_at>=$2 AND updated_at<$3`,[context.tenantId,since,to]),
        client.query<{record:ReviewRequest}>(`SELECT record FROM review_requests WHERE tenant_id=$1 AND feedback_status='negative' AND created_at>=$2 AND created_at<$3`,[context.tenantId,since,to]),
        client.query<ApprovalRequest>(`SELECT id,tenant_id AS "tenantId",location_id AS "locationId",request_type AS "requestType",reason,status,entity_type AS "entityType",entity_id AS "entityId",payload,created_at AS "createdAt",decided_at AS "decidedAt",decided_by AS "decidedBy",decision_note AS "decisionNote" FROM approval_requests WHERE tenant_id=$1 AND request_type='service_recovery' AND created_at>=$2 AND created_at<$3`,[context.tenantId,since,to]),
        client.query<{record:ProviderReconciliationRun}>('SELECT record FROM provider_reconciliation_runs WHERE tenant_id=$1 ORDER BY started_at DESC',[context.tenantId]),
        client.query<TenantRateLimitBucket>(`SELECT tenant_id AS "tenantId",location_id AS "locationId",kind,window_start AS "windowStart",window_end AS "windowEnd",request_count AS "requestCount",max_requests AS "maxRequests",updated_at AS "updatedAt" FROM tenant_rate_limit_buckets WHERE tenant_id=$1 AND updated_at>=$2 AND updated_at<$3`,[context.tenantId,since,to]),
        client.query<{record:AuditRecord|AuditRecordInput}>('SELECT record FROM audit_log WHERE tenant_id=$1 ORDER BY occurred_at,id',[context.tenantId]),
        client.query<{record:ModelUsageRecord}>('SELECT record FROM model_usage_records WHERE tenant_id=$1 AND occurred_at>=$2 AND occurred_at<$3',[context.tenantId,since,to]),
        client.query<{record:ModelPriceVersion}>('SELECT record FROM model_price_versions WHERE tenant_id=$1 ORDER BY model,effective_from DESC',[context.tenantId]),
        client.query<{record:ClientCohortSnapshot}>('SELECT record FROM client_cohort_snapshots WHERE tenant_id=$1 AND period_from=$2 AND period_to=$3 ORDER BY created_at DESC',[context.tenantId,since,to]),
        client.query<{record:SecurityIncident}>('SELECT record FROM security_incidents WHERE tenant_id=$1 ORDER BY opened_at DESC',[context.tenantId]),
      ])
      await client.query('COMMIT')
      return{portfolio,conversations:conversations.rows.map(row=>row.record),reviewRequests:reviews.rows.map(row=>row.record),serviceRecoveryApprovals:recoveryApprovals.rows,reconciliationRuns:reconciliation.rows.map(row=>row.record),rateLimitBuckets:rateLimits.rows,auditRecords:audit.rows.map(row=>row.record),modelUsageRecords:modelUsage.rows.map(row=>row.record),modelPriceVersions:modelPrices.rows.map(row=>row.record),clientCohortSnapshots:cohorts.rows.map(row=>row.record),securityIncidents:securityIncidents.rows.map(row=>row.record)}
    }catch(error){await client.query('ROLLBACK');throw error}finally{client.release()}
  }
