  async saveAgencyAccountWithAudit(context:TenantContext,value:AgencyAccount,evidence:AgencyAccessEvidence){requireAgencyAccountScope(context,value,evidence);const client=await this.pool.connect();try{await client.query('BEGIN');await client.query('SELECT pg_advisory_xact_lock(hashtext($1))',[`${value.tenantId}:agency-account`]);const current=await client.query<{record:AgencyAccount}>('SELECT record FROM agency_accounts WHERE tenant_id=$1 FOR UPDATE',[value.tenantId]);const existing=current.rows[0]?.record;if(!existing&&(value.createdBy!==context.userId||value.createdAt!==evidence.occurredAt))throw new Error('AGENCY_ACCOUNT_SCOPE_MISMATCH');if(existing&&(existing.id!==value.id||existing.createdBy!==value.createdBy||existing.createdAt!==value.createdAt))throw new Error('AGENCY_ACCOUNT_VERSION_CONFLICT');const result=await client.query<{record:AgencyAccount}>(`INSERT INTO agency_accounts (id,tenant_id,status,record,created_at,updated_at) VALUES ($1,$2,$3,$4,$5,$6) ON CONFLICT (tenant_id) DO UPDATE SET status=EXCLUDED.status,record=EXCLUDED.record,updated_at=EXCLUDED.updated_at RETURNING record`,[value.id,value.tenantId,value.status,value,value.createdAt,value.updatedAt]);await appendChainedAuditInTransaction(client,agencyAccountAudit(context,value,evidence));await client.query('COMMIT');return result.rows[0]!.record}catch(error){await client.query('ROLLBACK');throw error}finally{client.release()}}
