  async revokeAgencyGrant(context:TenantContext,id:string,revokedAt:string,reason:string){if(context.role!=='owner')throw new Error('OWNER_AGENCY_ACCESS_REQUIRED');const client=await this.pool.connect();try{await client.query('BEGIN');const selected=await client.query<{record:AgencyGrant}>('SELECT record FROM agency_grants WHERE id=$1 AND (agency_tenant_id=$2 OR client_tenant_id=$2) FOR UPDATE',[id,context.tenantId]);const value=selected.rows[0]?.record;if(!value){await client.query('ROLLBACK');return undefined}if(value.status==='revoked'){await client.query('COMMIT');return value}const revoked:AgencyGrant={...value,status:'revoked',revokedBy:context.userId,revokedAt,revokeReason:reason};const result=await client.query<{record:AgencyGrant}>(`UPDATE agency_grants SET status='revoked',revoked_at=$2,record=$3 WHERE id=$1 RETURNING record`,[id,revokedAt,revoked]);await client.query('COMMIT');return result.rows[0]!.record}catch(error){await client.query('ROLLBACK');throw error}finally{client.release()}}
  async revokeAgencyGrantWithAudit(context:TenantContext,id:string,revokedAt:string,reason:string,evidence:AgencyAccessEvidence){requireAgencyActionScope(context,revokedAt,evidence,reason);const client=await this.pool.connect();try{await client.query('BEGIN');const selected=await client.query<{record:AgencyGrant}>('SELECT record FROM agency_grants WHERE id=$1 AND (agency_tenant_id=$2 OR client_tenant_id=$2) FOR UPDATE',[id,context.tenantId]);const value=selected.rows[0]?.record;if(!value){await client.query('ROLLBACK');return undefined}const revoked:AgencyGrant=value.status==='revoked'?value:{...value,status:'revoked',revokedBy:context.userId,revokedAt,revokeReason:reason};if(value.status!=='revoked')await client.query(`UPDATE agency_grants SET status='revoked',revoked_at=$2,record=$3 WHERE id=$1`,[id,revokedAt,revoked]);await appendChainedAuditInTransaction(client,agencyRevocationAudit(context,revoked,reason,evidence));await client.query('COMMIT');return revoked}catch(error){await client.query('ROLLBACK');throw error}finally{client.release()}}
