  async buildClientDataSnapshot(context:TenantContext,clientId:string):Promise<ClientDataSnapshot>{
    const client=await this.pool.connect()
    try{
      await client.query('BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY')
      const values=[context.tenantId,context.locationId,clientId]
      const records=async<T>(table:string,predicate='client_id=$3',order='id')=>(await client.query<{record:T}>(`SELECT record FROM ${table} WHERE tenant_id=$1 AND location_id=$2 AND ${predicate} ORDER BY ${order}`,values)).rows.map(row=>row.record)
      const profile=(await client.query<{record:ClientProfile}>('SELECT record FROM client_profiles WHERE tenant_id=$1 AND location_id=$2 AND client_id=$3',values)).rows[0]?.record??null
      const conversations=await records<Conversation>('conversations')
      const messages=(await client.query<{record:ConversationMessage}>(`SELECT m.record FROM conversation_messages m JOIN conversations c ON c.id=m.conversation_id AND c.tenant_id=m.tenant_id AND c.location_id=m.location_id WHERE m.tenant_id=$1 AND m.location_id=$2 AND c.client_id=$3 ORDER BY m.created_at,m.id`,values)).rows.map(row=>row.record)
      const recoveryContacts=(await client.query<{id:string;tenantId:string;locationId:string;workflowJobId:string;clientId:string;workflowType:RecoveryContactAttempt['workflowType'];channel:RecoveryContactAttempt['channel'];status:RecoveryContactAttempt['status'];reservedAt:Date;sentAt:Date|null;providerMessageId:string|null}>(`SELECT id,tenant_id AS "tenantId",location_id AS "locationId",workflow_job_id AS "workflowJobId",client_id AS "clientId",workflow_type AS "workflowType",channel,status,reserved_at AS "reservedAt",sent_at AS "sentAt",provider_message_id AS "providerMessageId" FROM recovery_contact_attempts WHERE tenant_id=$1 AND location_id=$2 AND client_id=$3 ORDER BY reserved_at,id`,values)).rows.map(value=>({id:value.id,tenantId:value.tenantId,locationId:value.locationId,workflowJobId:value.workflowJobId,clientId:value.clientId,workflowType:value.workflowType,channel:value.channel,status:value.status,reservedAt:value.reservedAt.toISOString(),...(value.sentAt?{sentAt:value.sentAt.toISOString()}:{}),...(value.providerMessageId?{providerMessageId:value.providerMessageId}:{})}))
      const snapshot:ClientDataSnapshot={
        profile,
        consents:await records<ConsentRecord>('consents','client_id=$3','captured_at,id'),
        holds:await records<AppointmentHold>('appointment_holds'),
        bookings:await records<BookingRecord>('bookings'),
        waitlistEntries:await records<WaitlistEntry>('waitlist_entries'),
        conversations,
        messages,
        reviewRequests:await records<ReviewRequest>('review_requests'),
        recoveryContacts,
        conversationFollowups:await records<ConversationFollowupAttempt>('conversation_followup_attempts'),
        missedCallRecoveries:await records<MissedCallRecoveryAttempt>('missed_call_recovery_attempts'),
        messageDeliveries:await records<OutboundMessageDelivery>('outbound_message_deliveries'),
        events:await records<DomainEvent>('domain_events',`record->'payload'->>'clientId'=$3`,'occurred_at,event_id'),
        auditRecords:await records<AuditRecord|AuditRecordInput>('audit_log',`entity_type='client' AND entity_id=$3`,'occurred_at,id'),
      }
      await client.query('COMMIT')
      return snapshot
    }catch(error){await client.query('ROLLBACK');throw error}finally{client.release()}
  }
  async savePrivacyDataExportReceipt(value:PrivacyDataExportReceipt){const result=await this.pool.query<{recordCounts:PrivacyDataExportReceipt['recordCounts']}>(`INSERT INTO privacy_data_export_receipts (id,tenant_id,location_id,client_id,requested_by,reason,digest,record_counts,generated_at) VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9) RETURNING record_counts AS "recordCounts"`,[value.id,value.tenantId,value.locationId,value.clientId,value.requestedBy,value.reason,value.digest,value.recordCounts,value.generatedAt]);return{...value,recordCounts:result.rows[0]!.recordCounts}}
