  async reserveRealtimeVoiceCall(value:RealtimeVoiceCall){const client=await this.pool.connect();try{await client.query('BEGIN');const inserted=await client.query<{record:RealtimeVoiceCall}>('INSERT INTO realtime_voice_calls (call_id,tenant_id,location_id,provider_event_id,status,record,created_at,updated_at) VALUES ($1,$2,$3,$4,$5,$6,$7,$8) ON CONFLICT (call_id) DO NOTHING RETURNING record',[value.callId,value.tenantId,value.locationId,value.providerEventId,value.status,value,value.createdAt,value.updatedAt]);if(inserted.rows[0]){await client.query('COMMIT');return{call:inserted.rows[0].record,duplicate:false}}const selected=await client.query<{record:RealtimeVoiceCall;tenantId:string;locationId:string}>('SELECT record,tenant_id AS "tenantId",location_id AS "locationId" FROM realtime_voice_calls WHERE call_id=$1',[value.callId]);await client.query('COMMIT');const existing=selected.rows[0];if(!existing)throw new Error('Realtime voice call reservation disappeared');if(existing.tenantId!==value.tenantId||existing.locationId!==value.locationId)throw new Error('Realtime voice call scope collision');return{call:existing.record,duplicate:true}}catch(error){await client.query('ROLLBACK');throw error}finally{client.release()}}
