  async transitionRealtimeVoiceCall(context:TenantContext,callId:string,from:RealtimeVoiceCallStatus[],to:RealtimeVoiceCallStatus,updatedAt:string,errorCode?:string){const client=await this.pool.connect();try{await client.query('BEGIN');const selected=await client.query<{record:RealtimeVoiceCall}>('SELECT record FROM realtime_voice_calls WHERE call_id=$1 AND tenant_id=$2 AND location_id=$3 FOR UPDATE',[callId,context.tenantId,context.locationId]);const current=selected.rows[0]?.record;if(!current||!from.includes(current.status)){await client.query('ROLLBACK');return undefined}const updated:RealtimeVoiceCall={...current,status:to,updatedAt,...(errorCode?{errorCode}:{errorCode:undefined})};await client.query('UPDATE realtime_voice_calls SET status=$1,record=$2,updated_at=$3 WHERE call_id=$4 AND tenant_id=$5 AND location_id=$6',[to,updated,updatedAt,callId,context.tenantId,context.locationId]);await client.query('COMMIT');return updated}catch(error){await client.query('ROLLBACK');throw error}finally{client.release()}}
  async recordRealtimeVoiceCallSignal(context:TenantContext,callId:string,signal:RealtimeVoiceCallSignal,occurredAt:string){const client=await this.pool.connect();try{await client.query('BEGIN');const selected=await client.query<{record:RealtimeVoiceCall}>('SELECT record FROM realtime_voice_calls WHERE call_id=$1 AND tenant_id=$2 AND location_id=$3 FOR UPDATE',[callId,context.tenantId,context.locationId]);const current=selected.rows[0]?.record;if(!current||!['accepted','transferred'].includes(current.status)){await client.query('ROLLBACK');return undefined}const updated:RealtimeVoiceCall={...current,signals:{...current.signals,[signal]:current.signals?.[signal]??occurredAt},updatedAt:occurredAt};await client.query('UPDATE realtime_voice_calls SET record=$1,updated_at=$2 WHERE call_id=$3 AND tenant_id=$4 AND location_id=$5',[updated,occurredAt,callId,context.tenantId,context.locationId]);await client.query('COMMIT');return updated}catch(error){await client.query('ROLLBACK');throw error}finally{client.release()}}
