function requireClientCohortScope(context:TenantContext,value:ClientCohortSnapshot,evidence:ClientCohortEvidence){const digestEvidence:Record<string,unknown>={...value};delete digestEvidence.id;delete digestEvidence.snapshotDigest;const periodFrom=Date.parse(value.periodFrom);const periodTo=Date.parse(value.periodTo);const metrics=value.metrics;const counts=[metrics.completedBookingsConsidered,metrics.startCompletedBookings,metrics.endCompletedBookings,metrics.startActiveClients,metrics.endActiveClients,metrics.retainedClients,metrics.churnedClients,metrics.newlyActiveClients];const digest=createHash('sha256').update(canonicalJson(digestEvidence)).digest('hex');if(context.role!=='owner'||value.tenantId!==context.tenantId||value.createdBy!==context.userId||evidence.userId!==context.userId||value.createdAt!==evidence.occurredAt||!Number.isFinite(periodFrom)||!Number.isFinite(periodTo)||periodTo<=periodFrom||periodTo-periodFrom>31*86_400_000||Date.parse(value.startWindowFrom)!==periodFrom-180*86_400_000||Date.parse(value.endWindowFrom)!==periodTo-180*86_400_000||value.policyVersion!=='active-client-180d-v1'||value.activityWindowDays!==180||value.evidence!=='square_completed_bookings'||value.containsClientIdentities!==false||counts.some(count=>!Number.isInteger(count)||count<0)||metrics.startCompletedBookings>metrics.completedBookingsConsidered||metrics.endCompletedBookings>metrics.completedBookingsConsidered||metrics.retainedClients+metrics.churnedClients!==metrics.startActiveClients||metrics.retainedClients+metrics.newlyActiveClients!==metrics.endActiveClients||value.evidenceStatus!==(metrics.startActiveClients?'sufficient':'insufficient')||metrics.churnRate!==(metrics.startActiveClients?metrics.churnedClients/metrics.startActiveClients:null)||digest!==value.snapshotDigest)throw new Error('CLIENT_COHORT_SCOPE_MISMATCH')}
