function closedPostgresCircuit(context:Pick<TenantContext,'tenantId'|'locationId'>,provider:ProviderName,now:string):ProviderCircuitState{return{tenantId:context.tenantId,locationId:context.locationId,provider,state:'closed',consecutiveFailures:0,updatedAt:now}}
async function circuitLock(client:pg.PoolClient,context:Pick<TenantContext,'tenantId'|'locationId'>,provider:ProviderName){await client.query('SELECT pg_advisory_xact_lock(hashtext($1))',[`${context.tenantId}:${context.locationId}:${provider}:provider-circuit`])}
async function savePostgresCircuit(client:pg.PoolClient,value:ProviderCircuitState){await client.query(`INSERT INTO provider_circuit_breakers (tenant_id,location_id,provider,state,consecutive_failures,next_probe_at,probe_lease_until,record,updated_at) VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9) ON CONFLICT (tenant_id,location_id,provider) DO UPDATE SET state=EXCLUDED.state,consecutive_failures=EXCLUDED.consecutive_failures,next_probe_at=EXCLUDED.next_probe_at,probe_lease_until=EXCLUDED.probe_lease_until,record=EXCLUDED.record,updated_at=EXCLUDED.updated_at`,[value.tenantId,value.locationId,value.provider,value.state,value.consecutiveFailures,value.nextProbeAt??null,value.probeLeaseUntil??null,value,value.updatedAt])}
function postgresIncidentTransitionAllowed(from:SecurityIncidentStatus,to:Exclude<SecurityIncidentStatus,'open'>){return from==='open'&&(to==='contained'||to==='false_positive')||from==='contained'&&to==='resolved'}
